import React, { type ReactElement } from 'react'
import { type AbstractGridCellDefinition, DynamicTypeGridCellAbstract } from '../../dynamic-type-grid-cell-abstract'
import { injectable } from 'inversify'
import {
  TranslateCell
} from '@Pimcore/modules/element/dynamic-types/definitions/grid-cell/components/translate/translate-cell'

@injectable()
export class DynamicTypeGridCellTranslate extends DynamicTypeGridCellAbstract {
  readonly id = 'translate'

  getGridCellComponent (props: AbstractGridCellDefinition): ReactElement<AbstractGridCellDefinition> {
    return <TranslateCell { ...props } />
  }
}
